package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class WorkflowRepliesTest {
 private Map<String,Object> ui(boolean terminal){return new LinkedHashMap<>(Map.of("ui_run_id","ui-"+"a".repeat(64),"state",terminal?"failed":"running","terminal",terminal,"test_passed",false,"cleanup_verified",true,"job_id","job"));}
 private Map<String,Object> arguments(Map<String,Object> out){return TaskSessionService.object(TaskSessionService.object(out.get("next_call")).get("arguments"));}
 @Test public void activeRunProvidesExactObservationCall(){var out=WorkflowReplies.ui(ui(false));var a=arguments(out);assertEquals("ui",a.get("op"));var args=TaskSessionService.object(a.get("args"));assertEquals("wait",args.get("action"));assertEquals(ui(false).get("ui_run_id"),args.get("ui_run_id"));assertEquals(20000,args.get("timeout_ms"));assertFalse(args.containsKey("steps"));}
 @Test public void failedOrUnknownRunOnlyOffersOriginalDetails(){for(boolean unknown:List.of(false,true)){var input=ui(true);input.put("outcome_unknown",unknown);var out=WorkflowReplies.ui(input);assertEquals("details",TaskSessionService.object(arguments(out).get("args")).get("action"));assertEquals(false,out.get("test_passed"));assertEquals(unknown,out.get("outcome_unknown"));}}
 @Test public void passedAndRetainedRunDoesNotInventCleanupOrNewPlan(){var input=ui(true);input.put("test_passed",true);assertFalse(WorkflowReplies.ui(input).containsKey("next_call"));input.put("cleanup_verified",false);input.put("client_retained",true);assertFalse(WorkflowReplies.ui(input).containsKey("next_call"));input.put("client_retained",false);assertEquals("cleanup_preview",TaskSessionService.object(arguments(WorkflowReplies.ui(input)).get("args")).get("action"));}
 @Test public void compactViewPreservesFailuresWithoutValuesOrTimelines(){var input=ui(true);input.put("details",Map.of("value","SENSITIVE"));input.put("startup",Map.of("log","SENSITIVE"));input.put("preparation_progress",Map.of("stage","starting","logs","SENSITIVE"));input.put("summary",Map.of("failed_step_index",2,"success",false,"verified_steps",1,"total_steps",4,"values","SENSITIVE"));var out=WorkflowReplies.ui(input);assertFalse(out.toString().contains("SENSITIVE"));assertEquals(2,TaskSessionService.object(out.get("summary")).get("failed_step_index"));assertTrue(out.containsKey("details_call"));assertTrue(input.containsKey("details"));}
 @Test public void preparationKeepsFreshReadinessAndNeverSuggestsRestart(){for(String state:List.of("preparing","ready","outcome_unknown","blocked","cleaned")){var source=new LinkedHashMap<String,Object>(Map.of("preparation_id","prep-"+"b".repeat(64),"state",state,"terminal",!state.equals("preparing"),"ready",state.equals("ready"),"runtime",Map.of("ready",state.equals("ready"),"connected",false,"client_id","client","payload","SENSITIVE")));var out=WorkflowReplies.preparation(source);assertFalse(out.toString().contains("SENSITIVE"));assertEquals(state.equals("ready"),out.get("ready"));if(Set.of("ready","cleaned").contains(state))assertFalse(out.containsKey("next_call"));else assertTrue(Set.of("wait","details").contains(TaskSessionService.object(arguments(out).get("args")).get("action")));}}
 @Test public void waitTimeoutDoesNotReportSuccessOrRepeatWork()throws Exception{var calls=new java.util.concurrent.atomic.AtomicInteger();var out=WorkflowReplies.waitFor(null,0,()->false,()->{calls.incrementAndGet();return ui(false);});assertEquals(true,out.get("timed_out"));assertEquals(false,out.get("terminal"));assertEquals(false,out.get("test_passed"));assertEquals(1,calls.get());}
 @Test public void negativeWaitIsRejectedBeforeObservation(){assertThrows(IllegalArgumentException.class,()->WorkflowReplies.waitFor(null,-1,()->false,()->{throw new AssertionError();}));}
 @Test public void metricsClassifiesCompactOperationsWithoutRetainingArbitraryText(){var known=Set.of("edt_ui_run","edt_runtime_prepare","edt_operation_status");assertEquals("edt_ui_run",AgentMetrics.operationName("edt.run",Map.of("op","ui"),known::contains));assertEquals("edt_runtime_prepare",AgentMetrics.operationName("edt.run",Map.of("op","prepare"),known::contains));assertEquals("edt_operation_status",AgentMetrics.operationName("edt.task",Map.of("op","edt_operation_status"),known::contains));assertEquals("edt.help.contract",AgentMetrics.operationName("edt.help",Map.of("action","contract","op","SECRET"),known::contains));assertEquals("unresolved",AgentMetrics.operationName("edt.run",Map.of("op","SECRET"),known::contains));}
 @Test public void existingContractsExposeWaitWithoutAnotherTopLevelTool(){for(String schema:List.of(new com.codepilot1c.core.tools.development.EdtUiRunTool().getParameterSchema(),new com.codepilot1c.core.tools.development.EdtRuntimePrepareTool().getParameterSchema())){var props=com.google.gson.JsonParser.parseString(schema).getAsJsonObject().getAsJsonObject("properties");assertTrue(props.getAsJsonObject("action").getAsJsonArray("enum").toString().contains("wait"));assertEquals(25000,props.getAsJsonObject("timeout_ms").get("maximum").getAsInt());}}
 @Test public void metricsCountsEmptyStatusAndDiscoverySeparately(){var known=Set.of("edt_bridge_status");assertEquals("edt_bridge_status",AgentMetrics.operationName("edt.status",Map.of(),known::contains));assertEquals("edt.run.operations",AgentMetrics.operationName("edt.run",Map.of(),known::contains));}
 @Test public void cleanupJobContinuationOnlyObservesExactJob(){var call=WorkflowReplies.job("original-cleanup-job");assertEquals("edt.task",call.get("tool"));var outer=TaskSessionService.object(call.get("arguments"));assertEquals("edt_operation_status",outer.get("op"));assertEquals("original-cleanup-job",TaskSessionService.object(outer.get("args")).get("job_id"));assertEquals(true,TaskSessionService.object(outer.get("args")).get("compact"));}

 @Test public void cleanedOrBlockedPreparationCannotLeakOldReadyRuntime(){for(String state:List.of("cleaned","blocked","outcome_unknown")){var source=Map.<String,Object>of("preparation_id","prep-"+"f".repeat(64),"state",state,"terminal",true,"ready",false,"runtime",Map.of("ready",true,"connected",true,"client_id","old-client"));var out=WorkflowReplies.preparation(source);assertEquals(false,out.get("ready"));assertFalse(out.containsKey("runtime"));}}
 @Test public void compactUiRetainsResourceIdsForInterleavedObservation(){var source=ui(true);source.put("client_id","client");source.put("session_id","session");source.put("preparation_id","preparation");var out=WorkflowReplies.ui(source);assertEquals("client",out.get("client_id"));assertEquals("session",out.get("session_id"));assertEquals("preparation",out.get("preparation_id"));}

 @Test public void metricsBaselineReturnsOnlyDeltasAndDoesNotConsumeTheBaseline(){
  var before=AgentMetrics.baseline();assertFalse(before.containsKey("tools"));String id=(String)before.get("baseline_id");AgentMetrics.record("workflow_delta_test",10,20,5,false);var after=AgentMetrics.changes(id);var rows=(List<?>)after.get("tools");var row=rows.stream().map(x->(Map<?,?>)x).filter(x->"workflow_delta_test".equals(x.get("tool"))).findFirst().orElseThrow();assertEquals(1L,row.get("calls"));assertEquals(10L,row.get("request_bytes"));assertEquals(20L,row.get("response_bytes"));assertEquals(false,after.get("token_usage_measured"));assertEquals(after,AgentMetrics.changes(id));
 }
 @Test public void missingMetricsBaselineNeverInventsZeroDelta(){assertThrows(IllegalArgumentException.class,()->AgentMetrics.changes("metrics-missing"));}

 @Test public void runnerSetupFailureRetainsReasonWithoutOldReadiness(){var source=new LinkedHashMap<String,Object>(Map.of("preparation_id","prep-"+"d".repeat(64),"state","needs_runner_setup","ready",false,"terminal",true,"runtime",Map.of("reason","runner_profile_missing","ready",false,"connected",true)));var out=WorkflowReplies.preparation(source);assertEquals("runner_profile_missing",out.get("reason"));assertFalse(out.containsKey("runtime"));source.put("reason","current_binding_failure");assertEquals("current_binding_failure",WorkflowReplies.preparation(source).get("reason"));}

}
